def signal(obs):
    st = obs.state
    if 'pos' not in st:
        st['pos'] = {'IDX':0,'A':0,'B':0,'C':0}
        st['hold'] = 0  # steps held
        st['cooldown'] = 0
    def get(arr_asset, n):
        try:
            h = obs.hist(arr_asset,'mid',n)
        except:
            return None
        return h
    W = 100
    N = 120
    hA = get('A', N)
    hB = get('B', N)
    hC = get('C', N)
    hI = get('IDX', N)
    if hA is None or hB is None or hC is None or hI is None:
        return {}
    if len(hA)<W or len(hB)<W or len(hC)<W or len(hI)<W:
        return {}
    if not (np.isfinite(hA[-1]) and np.isfinite(hB[-1]) and np.isfinite(hC[-1]) and np.isfinite(hI[-1])):
        return {}
    basket = 0.3333*hA + 0.6667*hB + 0.1667*hC
    prem = hI - basket
    if not np.isfinite(prem[-1]):
        return {}
    # track hold counter
    # if we are in position, increment hold
    in_pos = abs(st['pos']['IDX'])>0.05
    if in_pos:
        st['hold'] += 10  # called every 10 steps
        st['cooldown'] = 0
    else:
        if st['cooldown']>0:
            st['cooldown'] -= 10
        st['hold']=0
    out = {}
    # entry only if flat and not in cooldown
    if not in_pos and st['cooldown']<=0:
        # use recent premium level directly, not z, to exploit asymmetry
        # entry threshold -11.5 ~ spread cost 11.3 plus 0.2 buffer
        if prem[-1] < -12.0:
            # also require that premium is below its recent mean to avoid buying in uptrend? check mean
            # compute recent mean/std for confirmation but threshold is absolute
            # need sufficient history to ensure not NaN
            recent = prem[-W:]
            valid = np.isfinite(recent)
            if np.sum(valid)>=80:
                mean = np.mean(recent[valid])
                # only enter if premium is still below mean (cheap relative to recent)
                if prem[-1] < mean:
                    # enter long IDX short basket
                    # scale 0.6 to stay within limits and allow hedged notional ~1:1
                    out['IDX'] = 0.6
                    out['A'] = -0.2  # 0.6*0.333
                    out['B'] = -0.4  # 0.6*0.666
                    out['C'] = -0.1  # 0.6*0.166
                    st['pos'] = {'IDX':0.6,'A':-0.2,'B':-0.4,'C':-0.1}
                    st['hold']=0
                    return out
        # no entry => stay flat (do not send)
        return {}
    elif in_pos:
        # exit conditions: hold at least 120 steps (12 calls) to capture reversion and reduce turnover
        # exit if premium reverted above -3 (near fair) or hold >150 steps or premium turned positive
        if st['hold'] >= 140:  # 14 calls *10 =140
            # time exit
            out['IDX']=0.0
            out['A']=0.0
            out['B']=0.0
            out['C']=0.0
            st['pos']={'IDX':0,'A':0,'B':0,'C':0}
            st['cooldown']=30
            return out
        if prem[-1] > -3.0:
            out['IDX']=0.0
            out['A']=0.0

def signal(obs):
    st = obs.state
    prev = float(st.get('pos', 0.0))
    try:
        ix = obs.hist('C.X', 'imbalance', 30)
        ic = obs.hist('C', 'imbalance', 30)
        mx = obs.hist('C.X', 'mid', 5)
        mc = obs.hist('C', 'mid', 5)
    except Exception:
        return {}
    try:
        n = ix.shape[0]
        if n < 20:
            return {}
        # smoothed imbalance (mean of last ~20, nan-aware)
        sx = 0.0; cx = 0
        for i in range(n - 20, n):
            v = float(ix[i])
            if v == v:
                sx += v; cx += 1
        sc = 0.0; cc = 0
        for i in range(n - 20, n):
            v = float(ic[i])
            if v == v:
                sc += v; cc += 1
        if cx < 10 or cc < 10:
            return {}
        ax = sx / cx
        ac = sc / cc
        a = float(mx[-1]); b = float(mc[-1])
        if not (a == a and b == b):
            return {}
        # combined cross-venue signal: weight X book more (it leads C)
        sig = 0.7 * ax + 0.3 * ac
        # hysteresis bands to cut turnover: enter at 0.12, exit at 0.03
        tgt = prev
        if prev > 0.5:
            if sig < 0.03:
                if sig < -0.12:
                    tgt = -1.0
                elif sig < 0.03:
                    tgt = 0.0
                else:
                    tgt = 1.0
            else:
                tgt = 1.0
        elif prev < -0.5:
            if sig > -0.03:
                if sig > 0.12:
                    tgt = 1.0
                elif sig > -0.03:
                    tgt = 0.0
                else:
                    tgt = -1.0
            else:
                tgt = -1.0
        else:
            if sig > 0.12:
                tgt = 1.0
            elif sig < -0.12:
                tgt = -1.0
            else:
                tgt = 0.0
        st['pos'] = float(tgt)
        if tgt == 0.0:
            # flatten
            return {'C': 0.0}
        return {'C': float(tgt)}
    except Exception:
        return {}

