    targets={}
    def zscore(asset, lb):
        m = obs.last(asset,'mid')
        hist = obs.hist(asset,'mid', lb+1)
        if hist is None or len(hist) < lb+1:
            return 0.0
        if hist[0] != hist[0] or m != m:
            return 0.0
        past = hist[0]
        if past != past:
            return 0.0
        ret = m - past
        h = obs.hist(asset,'mid', 70)
        if h is None or len(h) < 20:
            vol = 2.0
        else:
            s = 0.0
            s2 = 0.0
            n = 0
            for i in range(1, len(h)):
                a = h[i]
                b = h[i-1]
                if a == a and b == b:
                    d = a - b
                    s += d
                    s2 += d*d
                    n += 1
            if n < 10:
                vol = 2.0
            else:
                mean = s / n
                var = s2 / n - mean*mean
                if var < 0:
                    var = 0
                vol = math.sqrt(var) if var > 1e-9 else 2.0
                if vol < 0.6:
                    vol = 0.6
                if vol > 10:
                    vol = 10
        # normalized momentum
        return ret / (vol * math.sqrt(lb))
    for asset in ('A','C','IDX'):
        z = zscore(asset, 50)
        if z > 0.9:
            targets[asset] = 1.0
