def signal(obs):
    st = obs.state
    b = obs.last('B', 'mid')
    bx = obs.last('B.X', 'mid')
    if not (b == b and bx == bx):
        return {}
    diff = b - bx
    # scale by typical diff std ~6c
    t = diff / 8.0
    if t > 1: t = 1
    if t < -1: t = -1
    # deadband to cut turnover: ignore tiny diffs
    if abs(diff) < 2.0:
        t = 0.0
    prev = st.get('p', 0.0)
    if prev != prev:
        prev = 0.0
    if abs(t - prev) < 0.15:
        t = prev
    st['p'] = t
    # B leads B.X: fade cross-venue spread (long laggard, short leader), hedged same-stock pair
    return {'B': -t, 'B.X': t}

